package com.niranjankagri.aitesting.tests.ai;

import com.niranjankagri.aitesting.framework.BaseUiTest;
import com.niranjankagri.aitesting.framework.TestCase;
import com.niranjankagri.aitesting.framework.TestUsers;
import org.testng.annotations.Test;

import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;

/** TC-103: an employee books five working days of annual leave and the balance drops by five. */
public class SubmitAnnualLeaveTest extends BaseUiTest {

    @Test(groups = "ui")
    @TestCase("TC-103")
    public void tc103_annualLeaveRequestIsPendingAndReducesTheBalance() {
        // Arrange: alice on an empty calendar (BaseUiTest resets the data before every test)
        loginAs(TestUsers.EMPLOYEE);

        // Act: Monday 2 Nov to Friday 6 Nov 2026, no reason
        dashboardPage.submitRequest("ANNUAL", "2026-11-02", "2026-11-06", "");

        // Assert: confirmation, the new row, and 24 - 5 = 19 days left
        assertThat(dashboardPage.formSuccess()).hasText("Request #1 submitted (5 working days)");
        assertThat(dashboardPage.row(1)).isVisible();
        assertThat(dashboardPage.status(1)).hasText("PENDING");
        assertThat(dashboardPage.annualRemaining()).hasText("19");
    }
}
